import base64


def decompress(s):
    buf = list(base64.b85decode(s))
    nums = []
    i = 0
    while i < len(buf):
        if buf[i] == 63:
            nums.extend([-1] * buf[i + 1])
            i += 2
        else:
            nums.append(buf[i] - 7)
            i += 1
    return nums


arr = decompress(data)


CODE = []
X = Y = 0


def pu():
    global CODE
    CODE.append("SP,1")


def pd():
    global CODE
    CODE.append("SP,0")


STEPS_PER_INCH = 2032


def goto(x, y):
    global X, Y, CODE

    y = -y

    dm1 = int(round(((x + y) - (X + Y)) * STEPS_PER_INCH))
    dm2 = int(round(((x - y) - (X - Y)) * STEPS_PER_INCH))

    t = max(abs(dm1), abs(dm2))
    if t == 0:
        X, Y = x, y
        return

    CODE.append(f"SM,{t},{dm1},{dm2}")

    X, Y = x, y


PAGE_WIDTH = 11.0


def char_spacing(c):
    char = ord(c) - 32
    if char < 0 or char > 94:
        return 25
    return arr[char * 112 + 1]


def draw_string(s, scale=0.005):
    offset = (0, 0)
    pen_down = False

    lines = s.split("\n")
    for li, line in enumerate(lines):
        if li > 0:
            offset = (0, offset[1] - 25 * scale)
        words = line.split(" ")
        for wi, word in enumerate(words):
            ww = sum(char_spacing(c) for c in word) * scale
            if offset[0] > 0 and offset[0] + ww > PAGE_WIDTH:
                offset = (0, offset[1] - 25 * scale)

            for c in word:
                char = ord(c) - 32
                if char < 0 or char > 94:
                    offset = (offset[0] + 25 * scale, offset[1])
                    continue
                n_vertices = arr[char * 112]
                spacing = arr[char * 112 + 1]
                vertices = arr[char * 112 + 2 : char * 112 + 2 + n_vertices * 2]

                need_move = True
                for vi in range(0, len(vertices), 2):
                    if vertices[vi] == -1 and vertices[vi + 1] == -1:
                        if pen_down:
                            pu()
                            pen_down = False
                        need_move = True
                    else:
                        x = offset[0] + vertices[vi] * scale
                        y = offset[1] + vertices[vi + 1] * scale
                        if need_move:
                            if pen_down:
                                pu()
                                pen_down = False
                            goto(x, y)
                            pd()
                            pen_down = True
                            need_move = False
                        else:
                            goto(x, y)

                if pen_down:
                    pu()
                    pen_down = False

                offset = (offset[0] + spacing * scale, offset[1])

            if wi < len(words) - 1:
                offset = (offset[0] + char_spacing(" ") * scale, offset[1])


