import glob
import os
import termios
import time


def find_ebb():
    for p in glob.glob("/dev/ttyACM*") + glob.glob("/dev/ttyUSB*"):
        return p
    return None


def send(port_path=None):
    path = port_path or find_ebb()
    if not path:
        raise RuntimeError("No EBB device found")

    fd = os.open(path, os.O_RDWR | os.O_NOCTTY)

    attrs = termios.tcgetattr(fd)
    attrs[0] = 0  # iflag
    attrs[1] = 0  # oflag
    attrs[2] = termios.CS8 | termios.CREAD | termios.CLOCAL  # cflag
    attrs[3] = 0  # lflag
    attrs[4] = termios.B9600  # ispeed (EBB ignores baud but needs valid config)
    attrs[5] = termios.B9600  # ospeed
    attrs[6][termios.VMIN] = 1
    attrs[6][termios.VTIME] = 10
    termios.tcsetattr(fd, termios.TCSANOW, attrs)

    def write_cmd(cmd):
        os.write(fd, (cmd + "\r").encode())
        resp = b""
        while b"\r\n" not in resp:
            resp += os.read(fd, 64)
        return resp.decode().strip()

    PEN_DELAY = 0.15

    write_cmd("V")  # version check / wake
    for cmd in CODE:
        write_cmd(cmd)
        if cmd.startswith("SM,"):
            dur = int(cmd.split(",")[1])
            time.sleep(dur / 1000.0)
        elif cmd.startswith("SP,"):
            time.sleep(PEN_DELAY)

    os.close(fd)


def print(s):
    draw_string(s)
    send()
